import { couldBe, type LanguageCode } from '@lexpad/core';
import { PINNED_LANGUAGES, TARGET_LANGUAGES } from '@/features/settings/data.js';

/**
 * The language a typed word is written in, when its script says so. English
 * leads the languages people come here to learn and stays the default; a
 * word in another script (Persian, Russian, Japanese…) picks the language
 * that writes it, and when a script is shared (Persian, Urdu, Pashto and
 * Kurdish all write دلتنگی) the one the language list itself would put
 * first: the pinned pair, then the popular ones. It is only where the list
 * starts: the question is still asked, because it is the learner's choice.
 */
export function guessTarget(word: string): LanguageCode {
  const candidates = couldBe(word, TARGET_LANGUAGES);
  if (candidates.length === 0 || candidates.includes('en')) return 'en';
  const order = [...PINNED_LANGUAGES, ...TARGET_LANGUAGES];
  const rank = (code: LanguageCode): number => order.indexOf(code);
  return [...candidates].sort((a, b) => rank(a) - rank(b))[0] ?? 'en';
}
